module AppInstaller (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] n,\n    input wire [7:0] c,\n    input wire [7:0] d_0, s_0,\n    input wire [7:0] d_1, s_1,\n    input wire [7:0] d_2, s_2,\n    input wire [7:0] d_3, s_3,\n    input wire [7:0] d_4, s_4,\n    input wire [7:0] d_5, s_5,\n    input wire [7:0] d_6, s_6,\n    input wire [7:0] d_7, s_7,\n    output reg [2:0] max_count,\n    output reg [2:0] order_0,\n    output reg [2:0] order_1,\n    output reg [2:0] order_2,\n    output reg [2:0] order_3,\n    output reg [2:0] order_4,\n    output reg [2:0] order_5,\n    output reg [2:0] order_6,\n    output reg [2:0] order_7,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] PARTITION   = 3'd1;\n    localparam [2:0] SORT_B      = 3'd2;\n    localparam [2:0] SORT_A      = 3'd3;\n    localparam [2:0] BUILD_ORDER = 3'd4;\n    localparam [2:0] SIMULATE    = 3'd5;\n    localparam [2:0] FINISH      = 3'd6;\n\n    reg [2:0] state, next_state;\n    reg [7:0] apps_d [0:7];  // App download sizes\n    reg [7:0] apps_s [0:7];  // App installation sizes\n    reg [2:0] temp_order [0:7];\n    reg [2:0] group_b_count;\n    reg [2:0] group_a_count;\n    reg [7:0] current_capacity;\n    reg [2:0] install_idx;\n    integer i, j;\n    reg [2:0] temp_idx;\n    reg [2:0] sorted; // Sorting completion flag\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            max_count <= 3'd0;\n            done <= 1'b0;\n            group_b_count <= 3'd0;\n            group_a_count <= 3'd0;\n            install_idx <= 3'd0;\n            current_capacity <= 8'd0;\n            sorted <= 2'd0;\n            order_0 <= 3'd0; order_1 <= 3'd0; order_2 <= 3'd0; order_3 <= 3'd0;\n            order_4 <= 3'd0; order_5 <= 3'd0; order_6 <= 3'd0; order_7 <= 3'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                apps_d[i] <= 8'd0;\n                apps_s[i] <= 8'd0;\n                temp_order[i] <= 3'd7;\n            end\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:        if (start) next_state = PARTITION;\n            PARTITION:   next_state = SORT_B;\n            SORT_B:      if (sorted) next_state = SORT_A;\n            SORT_A:      if (sorted) next_state = BUILD_ORDER;\n            BUILD_ORDER: next_state = SIMULATE;\n            SIMULATE:    if (install_idx >= n || current_capacity < apps_d[temp_order[install_idx]]) next_state = FINISH;\n            FINISH:      next_state = IDLE;\n            default:     next_state = IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialization handled in state register\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        done <= 1'b0;\n                        apps_d[0] <= d_0; apps_s[0] <= s_0;\n                        apps_d[1] <= d_1; apps_s[1] <= s_1;\n                        apps_d[2] <= d_2; apps_s[2] <= s_2;\n                        apps_d[3] <= d_3; apps_s[3] <= s_3;\n                        apps_d[4] <= d_4; apps_s[4] <= s_4;\n                        apps_d[5] <= d_5; apps_s[5] <= s_5;\n                        apps_d[6] <= d_6; apps_s[6] <= s_6;\n                        apps_d[7] <= d_7; apps_s[7] <= s_7;\n                        current_capacity <= c;\n                        sorted <= 2'd0;\n                    end\n                end\n\n                PARTITION: begin\n                    group_b_count <= 3'd0;\n                    group_a_count <= 3'd0;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        temp_order[i] <= 3'd7;\n                    end\n                    sorted <= 2'd0;\n                end\n\n                SORT_B: begin\n                    if (sorted == 2'd0) begin\n                        // Partition into Groups\n                        group_b_count <= 3'd0;\n                        for (i = 0; i < n; i = i + 1) begin\n                            if (apps_d[i] > apps_s[i]) begin\n                                temp_order[group_b_count] <= i[2:0];\n                                group_b_count <= group_b_count + 3'd1;\n                            end\n                        end\n                        sorted <= 2'd1;\n                    end else begin\n                        // Bubble sort Group B by s descending\n                        for (i = 0; i < group_b_count - 1; i = i + 1) begin\n                            if (apps_s[temp_order[i]] < apps_s[temp_order[i+1]]) begin\n                                temp_idx = temp_order[i];\n                                temp_order[i] <= temp_order[i+1];\n                                temp_order[i+1] <= temp_idx;\n                            end\n                        end\n                    end\n                end\n\n                SORT_A: begin\n                    if (sorted == 2'd1) begin\n                        // Identify Group A\n                        group_a_count <= 3'd0;\n                        for (i = 0; i < n; i = i + 1) begin\n                            if (apps_d[i] <= apps_s[i]) begin\n                                temp_order[group_b_count + group_a_count] <= i[2:0];\n                                group_a_count <= group_a_count + 3'd1;\n                            end\n                        end\n                        sorted <= 2'd2;\n                    end else begin\n                        // Bubble sort Group A by d ascending\n                        for (i = group_b_count; i < group_b_count + group_a_count - 1; i = i + 1) begin\n                            if (apps_d[temp_order[i]] > apps_d[temp_order[i+1]]) begin\n                                temp_idx = temp_order[i];\n                                temp_order[i] <= temp_order[i+1];\n                                temp_order[i+1] <= temp_idx;\n                            end\n                        end\n                    end\n                end\n\n                BUILD_ORDER: begin\n                    order_0 <= temp_order[0];\n                    order_1 <= temp_order[1];\n                    order_2 <= temp_order[2];\n                    order_3 <= temp_order[3];\n                    order_4 <= temp_order[4];\n                    order_5 <= temp_order[5];\n                    order_6 <= temp_order[6];\n                    order_7 <= temp_order[7];\n                    install_idx <= 3'd0;\n                    current_capacity <= c;\n                    max_count <= 3'd0;\n                end\n\n                SIMULATE: begin\n                    if (install_idx < n) begin\n                        // Calculate required space (max(d, s))\n                        if (apps_d[temp_order[install_idx]] > apps_s[temp_order[install_idx]]) begin\n                            if (current_capacity >= apps_d[temp_order[install_idx]]) begin\n                                current_capacity <= current_capacity - apps_s[temp_order[install_idx]];\n                                max_count <= max_count + 3'd1;\n                                install_idx <= install_idx + 3'd1;\n                            end else begin\n                                install_idx <= n; // Can't install this app\n                            end\n                        end else begin\n                            if (current_capacity >= apps_s[temp_order[install_idx]]) begin\n                                current_capacity <= current_capacity - apps_s[temp_order[install_idx]];\n                                max_count <= max_count + 3'd1;\n                                install_idx <= install_idx + 3'd1;\n                            end else begin\n                                install_idx <= n; // Can't install this app\n                            end\n                        end\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule